<?php require __DIR__.'/config.php';if(($_GET['all']??'')==='1'){require_admin();$s=$pdo->query('SELECT id,name,category,description,price,image_url,is_available FROM products ORDER BY category,name');}else{$s=$pdo->query('SELECT id,name,category,description,price,image_url,is_available FROM products WHERE is_available=1 ORDER BY category,name');}json_out(['products'=>$s->fetchAll()]);?>